#messageList {
  margin: 0;
  padding: 0;
  list-style-type: none;

  & > li {
    position: relative;
    margin-block-end: 9px;
    padding-block-end: 9px;
    padding-inline: 12px 9px;
    border-block-end: 1px solid var(--layout-background-4);

    &.unread::before {
      position: absolute;
      inset-inline-start: -6px;
      inset-block-start: 8px;
      content: var(--icon-dot);
      -moz-context-properties: fill, stroke;
      fill: var(--color-green-50);
      stroke: var(--color-green-60);
      overflow: visible;
    }
  }
}

.star {
  inline-size: 16px;
  block-size: 16px;
  position: absolute;
  inset-inline-start: -7px;
  inset-block-start: 6px;
  background-repeat: no-repeat;

  .starred & {
    background-image: var(--icon-star);
    background-size: contain;
    -moz-context-properties: fill, stroke;
    fill: var(--thread-pane-flag-fill);
    stroke: var(--thread-pane-flag-stroke);
  }
